size_t min_group = min_bit / BITMAP_GROUP_BITS;
size_t bit_in_group = min_bit % BITMAP_GROUP_BITS;
size_t ngroups = binfo->ngroups;

for (size_t i = min_group; i < ngroups; ++i) {
    bitmap_t g = bitmap[i];
    if (g == std::numeric_limits<bitmap_t>::max()) {
        continue;
    }
    for (size_t j = bit_in_group; j < BITMAP_GROUP_BITS; ++j) {
        if (!(g & (static_cast<bitmap_t>(1) << j))) {
            return i * BITMAP_GROUP_BITS + j;
        }
    }
    bit_in_group = 0;
}
return binfo->nbits;
// END_CODE

